// --- FUNCIONES AUXILIARES ---

function escapeHtml(text) {
    if (!text) return '';
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function repairHtml(htmlText) {
    // Dividimos el texto en tokens: etiquetas vs texto
    // Regex captura: (< /? etiqueta ... >)
    const tokens = htmlText.split(/(<\/?(?:b|i|u|s|code|pre|a)[^>]*>)/gi);

    const result = [];
    const stack = [];
    const voidTags = new Set(['br', 'hr', 'img']);

    for (const token of tokens) {
        if (!token) continue;

        // ¿Es una etiqueta?
        const tagMatch = token.match(/^<\/?([a-z0-9]+)/i);

        if (tagMatch) {
            const tagName = tagMatch[1].toLowerCase();
            const isClosing = token.startsWith('</');

            if (isClosing) {
                // CIERRE
                if (stack.length === 0) {
                    // Cierre huérfano: lo ignoramos
                    continue;
                }

                if (stack[stack.length - 1] === tagName) {
                    // Cierre limpio (coincide con la última abierta)
                    stack.pop();
                    result.push(token);
                } else {
                    // CRUCE DETECTADO (Ej: stack=[b, i], llega </b>)
                    if (stack.includes(tagName)) {
                        // Cerramos todo lo que haya por encima
                        while (stack.length > 0) {
                            const top = stack.pop();
                            result.push(`</${top}>`);
                            if (top === tagName) break;
                        }
                        // Nota: Al cerrar 'b', también hemos cerrado 'i' implícitamente en HTML estricto
                        // Si quisieras reabrir 'i' después, la lógica sería más compleja,
                        // pero para Telegram/WhatsApp, cerrar todo es lo más seguro.
                    }
                    // Si no estaba en el stack, es un cierre inválido -> ignorar
                }
            } else {
                // APERTURA
                if (!voidTags.has(tagName)) {
                    stack.push(tagName);
                }
                result.push(token);
            }
        } else {
            // TEXTO NORMAL
            result.push(token);
        }
    }

    // Cerrar lo que quede abierto al final
    while (stack.length > 0) {
        result.push(`</${stack.pop()}>`);
    }

    return result.join('');
}

function toHtml(text) {
    if (!text) return "";

    const placeholders = [];
    function protect(content) {
        const id = `§§P${placeholders.length}§§`;
        placeholders.push(content);
        return id;
    }

    // 1. PROTEGER BLOQUES (Código y HTML ya existente)
    // ```code```
    text = text.replace(/```[\s\S]*?```/g, m => protect(m));
    // `code`
    text = text.replace(/`[^`\n]+`/g, m => protect(m));
    // HTML tags ya existentes (para no escapar sus < >)
    text = text.replace(/<\/?[a-z][^>]*>/gi, m => protect(m));

    // 2. ESCAPAR TEXTO PLANO
    text = escapeHtml(text);

    // 3. CONVERSIÓN MARKDOWN BÁSICA
    // Negrita **texto** -> <b>texto</b>
    text = text.replace(/\*\*(.*?)\*\*/gs, '<b>$1</b>');
    // Cursiva IA *(texto)* -> <i>(texto)</i>
    text = text.replace(/\*\((.*?)\)\*/gs, '<i>($1)</i>');
    // Cursiva normal *texto* (Lookaround simulado para no romper negritas)
    // En JS los lookbehind (?<!) no están en todos los entornos, usamos una lógica más segura:
    // Reemplazamos solo si no son **
    text = text.replace(/([^*]|^)\*([^*]+)\*([^*]|$)/g, '$1<i>$2</i>$3');

    // Listas - espacio -> •
    text = text.replace(/^(\s*)-\s/gm, '$1• ');

    // 4. RESTAURAR PROTEGIDOS
    // Lo hacemos en bucle inverso o varias pasadas por si hubo anidación (raro aquí)
    placeholders.forEach((content, i) => {
        text = text.split(`§§P${i}§§`).join(content);
    });

    // 5. REPARAR ESTRUCTURA
    return repairHtml(text);
}

// --- BUCLE PRINCIPAL N8N ---
for (const item of items) {
    const raw = item.json.output || item.json.text || '';
    item.json.html_output = toHtml(raw);
}

return items;
